before.run:
git config --global user.name 'Rajat Saxena'
git config --global user.email 'hi@sub.rajatsaxena.dev'
git remote set-url origin https://x-access-token:${{ secrets.PAT }}@github.com/${{ github.repository }}

after.run:
git config --global user.name 'CodeLit'
git config --global user.email 'hi@codelit.dev'
git remote set-url origin https://x-access-token:${{ secrets.PAT }}@github.com/${{ github.repository }}

before.run:
VERSION=${GITHUB_REF#refs/tags/v}
mike deploy --push --update-aliases "$VERSION" stable
mike set-default --push stable

after.run:
VERSION=${GITHUB_REF#refs/tags/v}
mike deploy --push --update-aliases "$VERSION" stable
mike set-default --push stable

configuration_differences.after:
CACHE_BUSTER_COMMIT=${{ github.sha }}
GOOGLE_MAPS_API_KEY=${{ github.ref == 'refs/heads/master' && secrets.GOOGLE_MAPS_API_KEY_PROD || secrets.GOOGLE_MAPS_API_KEY_DEV }}
CLOUDFLARE_TURNSTILE_SITE_KEY=${{ github.ref == 'refs/heads/master' && secrets.CLOUDFLARE_TURNSTILE_SITE_KEY_PROD || secrets.CLOUDFLARE_TURNSTILE_SITE_KEY_DEV }}
GITHUB_SHA=${{ github.ref != 'refs/heads/master' && github.sha || '' }}

uv venv
uv pip install .
echo "$(pwd)/.venv/bin" >> ${GITHUB_PATH}

configuration_differences.before:
echo "frontend changed: ${{ steps.check-changed-files.outputs.frontend_any_changed }}
echo "config changed: ${{ steps.check-changed-files.outputs.config_any_changed }}
echo "markdown changed: ${{ steps.check-changed-files.outputs.markdown_any_changed }}
echo "json changed: ${{ steps.check-changed-files.outputs.json_any_changed }}
echo "python changed: ${{ steps.check-changed-files.outputs.python_any_changed }}
echo "workflows changed: ${{ steps.check-changed-files.outputs.workflows_any_changed }}

after.run:
export NX_DAEMON=false
pnpm nx docker-build gateway
docker tag erxes/erxes-next-gateway erxes/erxes-next-gateway:latest
docker tag erxes/erxes-next-gateway erxes/erxes-next-gateway:${{ github.sha }}
docker push erxes/erxes-next-gateway:latest
docker push erxes/erxes-next-gateway:${{ github.sha }}

